import { test, expect } from '@playwright/test'

test("settings-light-mode", async ({ page }) => {
  // On this theme settings page, switch the Mode to Light. Stop when Light is the selected mode.
  await page.goto('/', { waitUntil: 'domcontentloaded' })
  const setup = await page.evaluate(async (reqs) => {
    const failed = []
    for (const r of reqs) {
      const init = { method: r.method, headers: { 'Content-Type': 'application/json' } }
      if (r.json !== null) init.body = JSON.stringify(r.json)
      const res = await fetch(r.path, init)
      if (!res.ok) failed.push(`${r.method} ${r.path} -> ${res.status}`)
    }
    return failed
  }, [{"method": "PUT", "path": "/api/config/theme", "json": {"mode": "dark"}}])
  expect(setup).toEqual([])
  await page.goto("/settings/display/theme", { waitUntil: 'domcontentloaded' })
  await page.getByRole("button", { name: "Light", exact: true }).click()
  await expect(
    page
      .locator('[aria-pressed="true"], [aria-selected="true"], [aria-checked="true"]')
      .filter({ hasText: "Light" })
      .first(),
  ).toBeVisible()
})
